\mathrm{df\text{-}metric\text{-}compact\text{-}net}\vdash\;\begin{aligned}
\mathsf{PtGrid}_{\mathcal A}(P)&\leftrightarrow\mathsf{Fun}(P,N\times_N(N\times_N N),A)\land\forall i,j\;\mathsf{Pt}_{\mathcal A}(P_{ij}),\\
\mathsf{Net}_{\mathcal A}(g,P)&\leftrightarrow\mathsf{Fun}(g,N,N)\land\forall j\;g(j)>0\land\mathsf{PtGrid}_{\mathcal A}(P)\\
&\quad\land\forall x\forall j[\mathsf{Pt}_{\mathcal A}(x)\to\exists i<g(j)\;\delta_{\mathcal A}(x,P_{ij})<_R\widehat{\varepsilon_j}],\\
\mathsf{Compact}(\mathcal A)&\leftrightarrow\mathsf{Met}(\mathcal A)\land\exists g\exists P\;\mathsf{Net}_{\mathcal A}(g,P).
\end{aligned}
